/* Managed authentication. Browser UI is not an authorization boundary: SQL enforces access. */
window.AssemblyAccount = (() => {
 const config=window.ASSEMBLY_AUTH_CONFIG||{};
 const configured=/^https:\/\/[a-z0-9-]+\.supabase\.co\/?$/.test(config.url||'') && /^sb_publishable_[A-Za-z0-9_-]+$/.test(config.publishableKey||'');
 let client=null,user=null,pendingReport=null,classes=[],reports=[],professor=false,epoch=0,joining=false,entered=false;
 const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const modal=document.createElement('dialog');modal.className='account-dialog';modal.setAttribute('aria-label','Account and saved agreements');document.getElementById('authEntry').append(modal);modal.show();document.getElementById('authLoading').hidden=true;modal.addEventListener('cancel',e=>{if(!entered)e.preventDefault()});
 const button=(text,action,cls='secondary')=>`<button type="button" class="${cls}" data-action="${action}">${escape(text)}</button>`;
 const message=(text,error=false)=>{const el=modal.querySelector('#accountStatus');if(el){el.textContent=text;el.classList.toggle('error',error)}};
 function shell(content){modal.innerHTML=(entered?'<button type="button" class="close" aria-label="Close account" data-action="close">&times;</button>':'')+(entered?'<span class="eyebrow">MY LEARNING SPACE</span>':'')+content+'<p id="accountStatus" class="account-status" role="status" aria-live="polite"></p>';}

 function unavailable(){shell('<h2>Your learning account</h2><p>Account sign-in is not connected yet. Please contact the course organizer to connect sign-in.</p><p>When enabled, your account will keep your saved agreements and let you submit work to a professor’s class.</p>');}
 async function open(report){if(report)pendingReport=JSON.parse(JSON.stringify(report));if(!modal.open){if(entered)modal.showModal();else modal.show();}if(!client){unavailable();return}shell('<h2>Your learning account</h2><p>Checking your session…</p>');await refresh();}
 async function refresh(){const e=++epoch;try{const {data,error}=await client.auth.getUser();if(e!==epoch)return;if(error||!data.user){user=null;professor=false;classes=[];reports=[];if(entered){location.reload();return}render();return}user=data.user;const [role,c,r,m]=await Promise.all([client.from('assembly_roles').select('role').eq('user_id',user.id).maybeSingle(),client.from('assembly_classes').select('id,title,teacher_id,join_code,accepting_members').order('created_at',{ascending:false}),client.from('assembly_reports').select('id,report_id,class_id,owner_id,created_at').order('created_at',{ascending:false}).limit(50),client.from('assembly_memberships').select('class_id').eq('user_id',user.id)]);if(e!==epoch)return;for(const result of [role,c,r,m])if(result.error)throw result.error;professor=role.data?.role==='professor';classes=c.data||[];reports=r.data||[];const allowed=AssemblyAccess.canEnter(user,professor,m.data||[]);if(!allowed&&entered){location.reload();return}if(allowed&&!entered){await window.AssemblyEntry.enter();entered=true;modal.close();document.body.append(modal);}render();}catch{shell('<h2>Account temporarily unavailable</h2><p>Your access could not be verified. Please try again.</p>'+button('Try again','refresh')+button('Sign out','signout'));message('Check the connection or contact the course organizer.',true);}}
 function joinForm(id='joinForm'){return '<form class="account-form" id="'+id+'"><label>Classroom code<input name="code" required pattern="[A-Za-z0-9]{12}" minlength="12" maxlength="12" placeholder="12-character class code" autocomplete="off"></label><button class="primary" type="submit">Join classroom</button></form>';}
 function render(){document.getElementById('accountLabel').textContent=user?'My work':'Account';if(!user){shell('<p class="auth-instruction">Choose how you would like to join.</p><details class="auth-option" name="entry-method"><summary><span><strong>Student</strong><small>Join with a classroom code</small></span><span class="auth-option-plus" aria-hidden="true"></span></summary><div class="auth-option-body">'+joinForm('studentJoinForm')+'<p class="micro-note">No email needed. Save your PDF before ending this browser session.</p></div></details><details class="auth-option" name="entry-method"><summary><span><strong>Professor</strong><small>Sign in to your teaching workspace</small></span><span class="auth-option-plus" aria-hidden="true"></span></summary><div class="auth-option-body">'+button('Sign in with Google','google','primary')+'<p class="micro-note">Use your approved professor account.</p><details class="email-alternative"><summary>Use an email link instead</summary><form class="account-form" id="signinForm"><label>Email address<input name="email" type="email" autocomplete="email" required maxlength="254"></label><button class="secondary" type="submit">Email me a sign-in link</button></form></details></div></details>');return}
 const options=classes.filter(c=>c.teacher_id!==user.id).map(c=>`<option value="${escape(c.id)}">${escape(c.title)}</option>`).join('');
 shell('<h2>'+ (professor?'Professor workspace':'My learning workspace')+'</h2><p>Signed in as <b>'+escape(user.is_anonymous?'Student '+user.id.slice(0,8):user.email)+'</b></p>'+(user.is_anonymous?'<p class="micro-note">Download your report before signing out. This browser-only student session cannot be recovered on another device. Your professor keeps reports you submitted.</p>':'')+button(user.is_anonymous?'End student session':'Sign out','signout')+(pendingReport?'<section class="account-card"><h3>Save this agreement</h3><p>'+escape(pendingReport.id)+'</p><label>Where to save<select id="saveClass"><option value="">Private — only me</option>'+options+'</select></label><p class="micro-note">Submitting to a class shares this report, your reflections and your account identifier with its professor. Reports are student-authored learning records, not verified grades.</p>'+button('Save agreement','save','primary')+'</section>':'')+joinForm()+(professor?'<form class="account-form" id="createForm"><label>New class title<input name="title" required maxlength="100" placeholder="Global health policy seminar"></label><button class="primary" type="submit">Create class</button></form>':'')+(!user.is_anonymous&&!professor?'<p class="note">Join a classroom using your professor&#39;s code to enter the simulation. Professor access is assigned separately by the project administrator.</p>':'')+'<h3>Your classes</h3>'+(classes.length?classes.map(c=>'<section class="account-card"><b>'+escape(c.title)+'</b>'+(c.teacher_id===user.id?'<p>Invite code: <code>'+escape(c.join_code)+'</code></p><p>'+ (c.accepting_members?'Open for joining':'Joining closed')+'</p>'+(c.accepting_members?button('Close joining','closeclass:'+c.id):button('Reopen joining','reopenclass:'+c.id))+button('Delete classroom','deleteclass:'+c.id):'<p>Joined · reports are shared only when submitted.</p>')+'</section>').join(''):'<p>No classes yet. Join a classroom to enter; approved professors can create one above.</p>')+'<h3>Saved agreements'+(professor?' and class submissions':'')+'</h3><p class="micro-note">Showing the latest 50 records. Saved agreements can be reviewed and downloaded; in-progress simulations are not saved.</p>'+(reports.length?reports.map(r=>'<section class="account-card"><b>'+escape(r.report_id)+'</b>'+(professor?'<p>Participant: '+escape(r.owner_id.slice(0,8))+'</p>':'')+'<p>'+escape(new Date(r.created_at).toLocaleDateString())+' · '+escape(classes.find(c=>c.id===r.class_id)?.title||'Private')+'</p>'+button('Review and download','view:'+r.id)+'</section>').join(''):'<p>Complete a simulation, then choose “Save agreement to my account”.</p>')+(entered?button('Return to simulation','close','primary'):''));
 }
 async function save(){if(!pendingReport||!user)return;const classId=modal.querySelector('#saveClass').value||null;const {data:verified,error:authError}=await client.auth.getUser();if(authError||verified.user?.id!==user.id)throw Error('Please sign in again before saving.');const {error}=await client.from('assembly_reports').upsert({owner_id:user.id,report_id:pendingReport.id,class_id:classId,report:pendingReport},{onConflict:'owner_id,report_id'});if(error)throw error;pendingReport=null;await refresh();message('Agreement saved.');}
 async function view(id){const {data,error}=await client.from('assembly_reports').select('report').eq('id',id).single();if(error)throw error;const r=data.report;if(!r||!Array.isArray(r.sections)||!Array.isArray(r.rows))throw Error('This report format cannot be displayed.');shell('<h2>Saved agreement</h2>'+Agreement.html(r)+button('Download PDF','download','primary')+button('Back to my work','refresh'));modal.querySelector('[data-action="download"]').onclick=()=>{const url=URL.createObjectURL(new Blob([Agreement.pdf(r)],{type:'application/pdf'}));const a=document.createElement('a');a.href=url;a.download=String(r.id).replace(/[^A-Za-z0-9_-]/g,'')+'.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};}
 modal.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const [action,id]=b.dataset.action.split(':');if(action==='close'){if(entered)modal.close();return}if(action==='download')return;b.disabled=true;try{if(action==='google'){const response=await fetch(config.url+'/auth/v1/settings',{headers:{apikey:config.publishableKey}});if(!response.ok)throw Error('Unable to check sign-in availability. Please try again.');const settings=await response.json();if(!settings.external?.google)throw Error('Google sign-in is awaiting setup by the project owner. Email sign-in remains available.');const {error}=await client.auth.signInWithOAuth({provider:'google',options:{redirectTo:new URL('index.html',location.href).href,queryParams:{prompt:'select_account'}}});if(error)throw error;}if(action==='refresh')await refresh();if(action==='signout'){epoch++;const {error}=await client.auth.signOut({scope:'local'});if(error)throw error;user=null;professor=false;reports=[];classes=[];pendingReport=null;render()}if(action==='save')await save();if(action==='view')await view(id);if(action==='deleteclass'){const classroom=classes.find(c=>c.id===id&&c.teacher_id===user?.id);if(!classroom)throw Error('Class not found');shell('<h2>Delete classroom?</h2><p><b>'+escape(classroom.title)+'</b></p><p>This permanently removes the classroom, invitation code and memberships. Students keep their saved reports privately, but you lose access to their submissions. Download any reports you need first. This cannot be undone.</p>'+button('Keep classroom','refresh','primary')+button('Permanently delete classroom','confirmdelete:'+id));}if(action==='confirmdelete'){const {error}=await client.rpc('assembly_delete_class',{target_id:id});if(error)throw error;await refresh();message('Classroom deleted. You can create a new class above.');}if(action==='reopenclass'){const {error}=await client.rpc('assembly_reopen_class',{target_id:id});if(error)throw error;await refresh();message('Joining is open again. Share the existing invite code.');}if(action==='closeclass'){const {error}=await client.rpc('assembly_close_class',{target_id:id});if(error)throw error;await refresh();message('Class joining is closed. Existing members retain access.')}}catch(err){message(err.code==='PGRST202'?'Classroom management needs a database update. Ask the project owner to run classroom-management.sql in Supabase.':err.message||'The request failed. Please try again.',true)}finally{b.disabled=false}});
 modal.addEventListener('submit',async e=>{e.preventDefault();const form=e.target;const b=form.querySelector('button');b.disabled=true;try{if(form.id==='studentJoinForm'){joining=true;try{const code=form.elements.code.value.trim();const {data:current}=await client.auth.getUser();if(!current.user){const {error}=await client.auth.signInAnonymously();if(error)throw error;}const {error}=await client.rpc('assembly_join_class',{code});if(error)throw error;await refresh();message('Classroom joined. Your report is shared only when you submit it.');}finally{joining=false;}}if(form.id==='signinForm'){const email=form.elements.email.value.trim();const redirect=new URL('index.html',location.href).href;const {error}=await client.auth.signInWithOtp({email,options:{emailRedirectTo:redirect}});if(error)throw error;message('Check your email for a sign-in link. Open it in this browser, then reopen Account.');}if(form.id==='joinForm'){const {error}=await client.rpc('assembly_join_class',{code:form.elements.code.value.trim()});if(error)throw error;await refresh();message('Class joined. Your existing private reports have not been shared.')}if(form.id==='createForm'){const {error}=await client.rpc('assembly_create_class',{class_title:form.elements.title.value.trim()});if(error)throw error;await refresh();message('Class created. Share the code with your students.')}}catch(err){message(err.message||'Unable to complete this request.',true)}finally{b.disabled=false}});
 if(configured&&window.createAssemblyAuthClient){try{client=window.createAssemblyAuthClient(config.url,config.publishableKey,{auth:{flowType:'pkce',storage:window.localStorage,storageKey:'assembly-auth',persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});client.auth.onAuthStateChange((event,session)=>{document.getElementById('accountLabel').textContent=session?'My work':'Account';if(event==='SIGNED_OUT'){if(entered){location.reload();return}epoch++;user=null;classes=[];reports=[];professor=false;pendingReport=null;render();}else if(event==='SIGNED_IN'&&!joining)setTimeout(refresh,0)});}catch{client=null}}
 if(client)refresh();else unavailable();
 window.addEventListener('focus',()=>{if(client&&entered)refresh()});
 return {open};
})();
